cat > src/main/java/GameOfLife.java <<'EOF'
import java.util.LinkedHashSet;
import java.util.Set;

public class GameOfLife {

    public Set<Cell> nextGeneration(Set<Cell> livingCells) {
        Set<Cell> nextGeneration = new LinkedHashSet<>();
        for (Cell cell : livingCells) {
            if (livingNeighborCount(cell, livingCells) == 2) {
                nextGeneration.add(cell);
            }
        }
        return nextGeneration;
    }

    private int livingNeighborCount(Cell cell, Set<Cell> livingCells) {
        int count = 0;
        for (int dx = -1; dx <= 1; dx++) {
            for (int dy = -1; dy <= 1; dy++) {
                if (dx == 0 && dy == 0) {
                    continue;
                }
                if (livingCells.contains(new Cell(cell.x() + dx, cell.y() + dy))) {
                    count++;
                }
            }
        }
        return count;
    }
}
EOF
