import java.util.LinkedHashSet;
import java.util.Set;

public class GameOfLife {

    private static final int NEIGHBORS_REQUIRED_TO_SURVIVE = 2;

    public Set<Cell> nextGeneration(Set<Cell> livingCells) {
        Set<Cell> nextGeneration = new LinkedHashSet<>();
        for (Cell cell : livingCells) {
            if (survives(cell, livingCells)) {
                nextGeneration.add(cell);
            }
        }
        return nextGeneration;
    }

    private boolean survives(Cell livingCell, Set<Cell> livingCells) {
        return livingNeighborCount(livingCell, livingCells) == NEIGHBORS_REQUIRED_TO_SURVIVE;
    }

    private int livingNeighborCount(Cell cell, Set<Cell> livingCells) {
        int count = 0;
        for (Cell neighbor : cell.neighbors()) {
            if (livingCells.contains(neighbor)) {
                count++;
            }
        }
        return count;
    }
}
import java.util.LinkedHashSet;
import java.util.Set;

public record Cell(int x, int y) {

    public Set<Cell> neighbors() {
        Set<Cell> neighbors = new LinkedHashSet<>();
        for (int dx = -1; dx <= 1; dx++) {
            for (int dy = -1; dy <= 1; dy++) {
                if (dx != 0 || dy != 0) {
                    neighbors.add(new Cell(x + dx, y + dy));
                }
            }
        }
        return neighbors;
    }
}
